DROP VIEW IF EXISTS replset.vw_month_adm_expenses CASCADE;  CREATE OR REPLACE VIEW replset.vw_month_adm_expenses AS  SELECT date_trunc('month'::text, date_period) AS repmonth,     organization_code AS orgs_code,     shop_code,     cost_item_code,     cost_item_name,     sum(amount) AS amount,     sum(amountvat) AS amountvat,     sum(amountwithvat) AS amountwithvat    FROM vw_expenses_adm   GROUP BY (date_trunc('month'::text, date_period)), organization_code, shop_code, cost_item_code, cost_item_name;
